using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

var mlContext = new MLContext(seed: 42);

var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
var modelPath = Path.Combine(AppContext.BaseDirectory, "model.zip");

// Load data — Churned is "Yes"/"No" so load as string, convert in pipeline
var data = mlContext.Data.LoadFromTextFile<CustomerData>(
    dataPath, hasHeader: true, separatorChar: ',');

var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

// Build pipeline: convert "Yes"/"No" to bool label, encode Region, concatenate features
var pipeline = mlContext.Transforms.CustomMapping<CustomerData, CustomerLabel>(
        (input, output) => { output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase); },
        contractName: "ChurnedToLabel")
    .Append(mlContext.Transforms.Categorical.OneHotEncoding("EncodedRegion", nameof(CustomerData.Region)))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(CustomerData.Age),
        nameof(CustomerData.Income),
        "EncodedRegion",
        nameof(CustomerData.PurchaseHistory)))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label", featureColumnName: "Features"));

Console.WriteLine("Training model...");
var model = pipeline.Fit(split.TrainSet);

// Evaluate
var predictions = model.Transform(split.TestSet);
var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
Console.WriteLine($"Accuracy: {metrics.Accuracy:F4}");
Console.WriteLine($"AUC:      {metrics.AreaUnderRocCurve:F4}");
Console.WriteLine($"F1 Score: {metrics.F1Score:F4}");

// Save model
mlContext.Model.Save(model, data.Schema, modelPath);
Console.WriteLine($"Model saved to {modelPath}");

// Register PredictionEnginePool
builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
    .FromFile(modelPath: modelPath);

var app = builder.Build();

app.MapGet("/", () => "Hello");

app.MapPost("/predict", (CustomerPredictRequest request,
    PredictionEnginePool<CustomerData, ChurnPrediction> pool) =>
{
    var input = new CustomerData
    {
        Age = request.Age,
        Income = request.Income,
        Region = request.Region ?? "",
        PurchaseHistory = request.PurchaseHistory,
        Churned = "No" // placeholder, not used for prediction
    };

    var prediction = pool.Predict(input);
    return Results.Ok(new
    {
        prediction.PredictedLabel,
        prediction.Probability,
        prediction.Score
    });
});

app.Run();

// --- Model classes ---

public class CustomerData
{
    [LoadColumn(0)] public float Age { get; set; }
    [LoadColumn(1)] public float Income { get; set; }
    [LoadColumn(2)] public string Region { get; set; } = string.Empty;
    [LoadColumn(3)] public float PurchaseHistory { get; set; }
    [LoadColumn(4)] public string Churned { get; set; } = string.Empty;
}

public class CustomerLabel
{
    public bool Label { get; set; }
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }
    public float Probability { get; set; }
    public float Score { get; set; }
}

public class CustomerPredictRequest
{
    public float Age { get; set; }
    public float Income { get; set; }
    public string? Region { get; set; }
    public float PurchaseHistory { get; set; }
}

